class Solution {
public:
    int lastRemaining(int n) {
        long long head = 1;
        long long step = 1;
        long long count = n;
        bool left = true;
        while (count > 1) {
            if (left || (count % 2 == 1)) {
                head += step;
            }
            step *= 2;
            count /= 2;
            left = !left;
        }
        return (int)head;
    }
};
